action.command:
su - dev -c 'cd /workspace && export PATH=$HOME/.local/bin:$PATH && ddev exec php -r "
\$pdo = new PDO('\"mysql:host=db;dbname=db\"', 'db','db');
\$hash = password_hash('\"Test1234\"', PASSWORD_BCRYPT);
\$st = \$pdo->prepare('\"UPDATE user SET password=:p WHERE id=1\"');
\$st->execute(['\":p\"'=>\$hash]);
echo 'updated rows: ' . \$st->rowCount() . PHP_EOL;
echo 'new hash: ' . \$hash . PHP_EOL;
"' 2>&1 | grep -v "Xdebug"

